type SearchProjectsInput = {
    /** Filter by category */
    category?: "Infrastructure" | "Tooling" | "User-Facing App" | "Asset" | "Protocol/Contract" | "Anchor" | "Partner Integration";
    /** Comma-separated top-level field names to return per row (e.g. fields=name,slug,tvlUSD), shrinking the payload. Case-insensitive. Each row's identity keys (id/slug/fullName/githubUsername/url/source, where present) are always included; unknown names are ignored, not rejected. Applies only to the rows array — meta is unaffected. Nested objects are selected whole (no dot-paths). */
    fields?: string;
    /** Max results per page. The default and cap VARY by endpoint (e.g. projects/search 20/100, builders 50/200, leaderboard 50/300, research 8/25). A value below 1 or above the cap is clamped, not rejected. */
    limit?: number;
    /** Number of matching rows to skip before returning (pagination). Page until offset + meta.counts.returned >= meta.counts.total. */
    offset?: number;
    /** Keyword query (free text) */
    q?: string;
    /** Filter to SCF-funded projects only */
    scfAwarded?: boolean;
    /** Filter by lifecycle status (e.g. status=Inactive lists retired/defunct projects; status=Live restricts to operating ones). Compose with scfAwarded for accountability/diligence — `?scfAwarded=1&status=Inactive` is the roster of SCF-funded projects that have since gone inactive, and `meta.counts.total` is how many. Unknown values return 400 with validStatuses. */
    status?: "Development" | "Pre-Release" | "Live" | "Inactive";
    /** Filter to projects whose `types[]` includes this product type — server-side exact membership, e.g. `type=Wallet` enumerates Wallet-typed records (combine with `q` and/or `status` to scope further, or use alone to list a type). Distinct from `category` (a project has ONE category but can carry several types). Unknown values return 400 with validTypes. */
    type?: "Wallet" | "DEX" | "Lending" | "Bridge" | "Infrastructure" | "Payments" | "Anchor" | "SDK" | "Indexer" | "Explorer" | "Analytics" | "AI" | "Gaming" | "Education" | "Security" | "NFT" | "RWA" | "Stablecoin" | "Social Impact" | "RPC" | "Faucet" | "Card Issuing" | "Exchange" | "Oracle" | "Yield";
}
type SearchProjectsOutput = { /* 3 top-level fields: codeReferences, meta, projects — full shape via codemode.describe("scout.searchProjects") */ }
scout.searchProjects(input: SearchProjectsInput): Promise<{ ok: true, data: SearchProjectsOutput } | { ok: false, error: { kind: "error" | "soft-empty", message: string, hint?: string } }>

