type SearchContentSemanticInput = {
    /** ISO date/timestamp upper bound (inclusive). */
    date_end?: string;
    /** For articles only: force a specific date field. Default is COALESCE(publishing_date, created_at). */
    date_field?: "publishing_date" | "created_at";
    /** ISO date/timestamp lower bound (inclusive). For articles, applies to COALESCE(publishing_date, created_at) by default to avoid stale re-scrape pollution. */
    date_start?: string;
    /** Max results per content type (default 20). Effective rows = limit × number of types — keep it small and narrow `types` instead of raising it. */
    limit?: number;
    /** Search query text */
    query: string;
    /** 'concise' omits long_summary from each row (smaller payloads); 'detailed' keeps it. Default: detailed. */
    response_format?: "concise" | "detailed";
    /** Filter by source. For articles: domain. For AV: channel. For events: platform. For tweets: user_screen_name. */
    sources?: string[];
    /** Restrict to specific content types. Default: all 9 (knowledge = internal dated notes). Narrow this for smaller, faster results — fanning out across all types multiplies the row count. */
    types?: "articles" | "av" | "events" | "research" | "proposals" | "tweets" | "twitter_accounts" | "scf_submissions" | "knowledge"[];
}
type SearchContentSemanticOutput = {
    /** Upstream row count for every returned collection. */
    counts: {
        [key: string]: number;
    };
    /** All upstream candidate rows in one globally similarity-sorted list. Each row carries its original collection. */
    items: {
        /** The upstream result collection, for example articles, events, av, or research. */
        collection: string;
        /** Best available upstream item timestamp. Interpret it using dateField; it is not automatically a publication or observation date. */
        date?: string;
        /** Exact upstream field copied into date, such as publishing_date, start_at, or created_at. */
        dateField?: string;
        /** Canonical concise text selected from upstream snippet/summary/description fields when present. */
        snippet?: string;
        /** Canonical source label selected from upstream source/domain/channel/platform fields when present. */
        source?: string;
        /** Exact upstream field copied into source. */
        sourceField?: string;
        /** Canonical display title selected from upstream title/name fields when present. */
        title?: string;
        /** Canonical item URL selected from upstream url/link fields when present. */
        url?: string;
        [key: string]: unknown;
    }[];
    /** Non-collection upstream metadata preserved without reshaping. */
    meta: {
        [key: string]: unknown;
    };
}
lumenloop.search_content_semantic(input: SearchContentSemanticInput): Promise<{ ok: true, data: SearchContentSemanticOutput } | { ok: false, error: { kind: "error" | "soft-empty", message: string, hint?: string } }>

